//! Sequence-logo letter outlines, baked into source.
//!
//! Each glyph is a path in font units (y-up) from DejaVu Sans Mono Bold, with
//! quadratics already elevated to cubics, plus its outline bounding box. The
//! logo renderer stretches the box onto each letter's cell. Bold Mono rather
//! than Sans because the stretch flattens a glyph that is a bare rectangle:
//! Sans Bold's `I` is a plain box, Mono's has serifs.
//!
//! Generated by `examples/gen_logo_glyphs.rs`; see there to regenerate.

mod data;

/// One letter outline. Coordinates are font units, y-up.
pub(crate) struct LogoGlyph {
    pub(crate) ch: char,
    /// SVG path `d` using only `M L C Z`.
    pub(crate) path: &'static str,
    pub(crate) x_min: f64,
    pub(crate) y_min: f64,
    pub(crate) x_max: f64,
    pub(crate) y_max: f64,
}

/// The outline for `c`, or `None` when it has none (the renderer then draws a
/// filled box with the letter centred in it).
pub(crate) fn glyph(c: char) -> Option<&'static LogoGlyph> {
    data::LOGO_GLYPHS
        .binary_search_by_key(&c, |g| g.ch)
        .ok()
        .map(|i| &data::LOGO_GLYPHS[i])
}

#[cfg(test)]
#[path = "extract.rs"]
mod extract;

#[cfg(test)]
mod tests {
    use super::*;

    /// The committed table must equal a fresh extraction from the bundled font.
    /// If this fails, run `cargo run --example gen_logo_glyphs && cargo fmt`.
    #[test]
    fn committed_table_matches_font() {
        let font = std::fs::read(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/assets/fonts/DejaVuSansMono-Bold.ttf"
        ))
        .unwrap();
        let fresh = extract::extract(&font);
        assert_eq!(fresh.len(), data::LOGO_GLYPHS.len(), "glyph count drifted");
        for (f, c) in fresh.iter().zip(data::LOGO_GLYPHS) {
            assert_eq!(f.ch, c.ch);
            assert_eq!(f.path, c.path, "outline of {:?} drifted", c.ch);
            assert_eq!(
                f.bbox,
                [c.x_min, c.y_min, c.x_max, c.y_max],
                "bbox of {:?}",
                c.ch
            );
        }
    }

    #[test]
    fn lookup_covers_letters_and_gap() {
        for c in ('A'..='Z').chain(['-', 'a', '0']) {
            assert!(glyph(c).is_some(), "{c:?} missing");
        }
        assert!(glyph('é').is_none());
    }
}
